import{_ as i,o as t,c as a,a2 as s}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"07. Practical Curriculum Guide: Yocto, Device Trees & Zynq Bring-Up","description":"","frontmatter":{},"headers":[],"relativePath":"07-zynq-yocto-dtc-tutorial-guide.md","filePath":"07-zynq-yocto-dtc-tutorial-guide.md"}'),o={name:"07-zynq-yocto-dtc-tutorial-guide.md"};function n(d,e,l,r,c,p){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="_07-practical-curriculum-guide-yocto-device-trees-zynq-bring-up" tabindex="-1">07. Practical Curriculum Guide: Yocto, Device Trees &amp; Zynq Bring-Up <a class="header-anchor" href="#_07-practical-curriculum-guide-yocto-device-trees-zynq-bring-up" aria-label="Permalink to &quot;07. Practical Curriculum Guide: Yocto, Device Trees &amp; Zynq Bring-Up&quot;">​</a></h1><p>This guide outlines a structured, hands-on learning roadmap for teaching juniors how to build custom Embedded Linux systems, write/modify Device Trees (<code>.dts</code>/<code>.dtsi</code>), and master the Yocto Project targeting <strong>Xilinx Zynq-7000 hardware (ZedBoard, PYNQ-Z1, or PYNQ-Z2)</strong>.</p><hr><h2 id="📺-recommended-video-reference-library" tabindex="-1">📺 Recommended Video Reference Library <a class="header-anchor" href="#📺-recommended-video-reference-library" aria-label="Permalink to &quot;📺 Recommended Video Reference Library&quot;">​</a></h2><p>When teaching juniors, recommend these specific video courses and channels organized by domain:</p><h3 id="category-1-device-tree-dts-dtb-dtc-overlays" tabindex="-1">Category 1: Device Tree (DTS, DTB, DTC &amp; Overlays) <a class="header-anchor" href="#category-1-device-tree-dts-dtb-dtc-overlays" aria-label="Permalink to &quot;Category 1: Device Tree (DTS, DTB, DTC &amp; Overlays)&quot;">​</a></h3><ol><li><strong>Bootlin (formerly Free Electrons) – Device Tree for Unix Developers:</strong><ul><li><em>Presenter:</em> Thomas Petazzoni / Grégory Clément.</li><li><em>Why it&#39;s essential:</em> Explains hardware description syntax, node hierarchy, memory maps (<code>reg</code>), interrupt controllers, clock bindings, and how the Linux kernel parses DTBs at boot.</li></ul></li><li><strong>FastBit Embedded Brain Academy (Kiran Nayak) – Linux Device Driver &amp; Device Tree:</strong><ul><li><em>Why it&#39;s essential:</em> Detailed line-by-line breakdown of editing <code>.dts</code> files, compiling with <code>dtc</code> (<code>dtc -I dts -O dtb -o devicetree.dtb system.dts</code>), and inspecting <code>/proc/device-tree</code> on target hardware.</li></ul></li><li><strong>Low Level Learning – What is a Device Tree in Linux?</strong><ul><li><em>Why it&#39;s essential:</em> A concise 10-minute conceptual primer ideal for juniors before diving into complex syntax.</li></ul></li></ol><h3 id="category-2-yocto-project-openembedded" tabindex="-1">Category 2: Yocto Project &amp; OpenEmbedded <a class="header-anchor" href="#category-2-yocto-project-openembedded" aria-label="Permalink to &quot;Category 2: Yocto Project &amp; OpenEmbedded&quot;">​</a></h3><ol><li><strong>Bootlin – Yocto Project &amp; OpenEmbedded Training (Full Video Series + Slides):</strong><ul><li><em>Why it&#39;s essential:</em> The industry standard training course covering Poky, BitBake syntax, <code>.bb</code> recipes, <code>.bbappend</code> overrides, layer creation (<code>meta-custom</code>), and <code>conf/local.conf</code>.</li></ul></li><li><strong>BOPV (YouTube) – Yocto Linux #1: Initial Setup and ZedBoard Bring-Up:</strong><ul><li><em>Why it&#39;s essential:</em> A direct, practical video series walking through setting up Yocto specifically for the Xilinx ZedBoard (Zynq Z7020) using <code>meta-xilinx</code>.</li></ul></li><li><strong>Digi-Key / Shawn Hymel – Introduction to Embedded Linux Series:</strong><ul><li><em>Why it&#39;s essential:</em> Excellent high-level overview of bootloaders (U-Boot), kernel compilation, root filesystem generation, and system initialization.</li></ul></li></ol><h3 id="category-3-xilinx-zynq-7000-zedboard-pynq-hardware-bring-up" tabindex="-1">Category 3: Xilinx Zynq-7000 (ZedBoard / PYNQ) Hardware Bring-Up <a class="header-anchor" href="#category-3-xilinx-zynq-7000-zedboard-pynq-hardware-bring-up" aria-label="Permalink to &quot;Category 3: Xilinx Zynq-7000 (ZedBoard / PYNQ) Hardware Bring-Up&quot;">​</a></h3><ol><li><strong>Xilinx / AMD Developer Community Talks:</strong><ul><li><em>Focus:</em> Hardware Handoff (<code>.xsa</code> / <code>.hdf</code>) from Vivado to Yocto/PetaLinux, First Stage Bootloader (FSBL), U-Boot second-stage bootloader, and FPGA bitstream loading.</li></ul></li><li><strong>PYNQ Official Tutorials (pynq.io):</strong><ul><li><em>Focus:</em> How <code>meta-xilinx</code> and <code>meta-pynq</code> layers configure UIO drivers, DMA, and FPGA overlays on PYNQ-Z1 / PYNQ-Z2 boards.</li></ul></li></ol><hr><h2 id="🛣️-step-by-step-4-phase-junior-training-roadmap" tabindex="-1">🛣️ Step-by-Step 4-Phase Junior Training Roadmap <a class="header-anchor" href="#🛣️-step-by-step-4-phase-junior-training-roadmap" aria-label="Permalink to &quot;🛣️ Step-by-Step 4-Phase Junior Training Roadmap&quot;">​</a></h2><p>Structure your practical labs into 4 sequential phases so students build confidence progressively:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Phase 1: Linux Boot &amp; DT Basics] ──&gt; [Phase 2: Vivado Hardware Handoff] ──&gt; [Phase 3: Yocto Build System] ──&gt; [Phase 4: FPGA Overlay &amp; DTC]</span></span></code></pre></div><h3 id="phase-1-manual-device-tree-compilation-inspection" tabindex="-1">Phase 1: Manual Device Tree Compilation &amp; Inspection <a class="header-anchor" href="#phase-1-manual-device-tree-compilation-inspection" aria-label="Permalink to &quot;Phase 1: Manual Device Tree Compilation &amp; Inspection&quot;">​</a></h3><ul><li><strong>Goal:</strong> Understand hardware description without complex build systems.</li><li><strong>Hands-On Tasks:</strong><ol><li>Decompile an existing board DTB:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dtc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dtb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> decompiled.dts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system.dtb</span></span></code></pre></div></li><li>Edit <code>decompiled.dts</code> to modify a serial port baud rate or add a dummy memory-mapped peripheral node.</li><li>Recompile with <code>dtc</code>:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dtc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dtb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> custom_system.dtb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> decompiled.dts</span></span></code></pre></div></li><li>Inspect runtime hardware representation in Linux via <code>/sys/firmware/devicetree/base</code> and <code>/proc/device-tree</code>.</li></ol></li></ul><hr><h3 id="phase-2-vivado-block-design-to-hardware-handoff-xsa" tabindex="-1">Phase 2: Vivado Block Design to Hardware Handoff (<code>.xsa</code>) <a class="header-anchor" href="#phase-2-vivado-block-design-to-hardware-handoff-xsa" aria-label="Permalink to &quot;Phase 2: Vivado Block Design to Hardware Handoff (`.xsa`)&quot;">​</a></h3><ul><li><strong>Goal:</strong> Understand how hardware registers in FPGA logic map to Linux memory.</li><li><strong>Hands-On Tasks:</strong><ol><li>Create a basic Zynq-7000 processing system design in Vivado for ZedBoard or PYNQ-Z1/Z2.</li><li>Add AXI GPIO peripherals connected to onboard LEDs and pushbuttons.</li><li>Export Hardware Definition (<code>.xsa</code> / Xilinx Shell Archive).</li><li>Understand how Xilinx Device Tree Generator (DTG) converts <code>.xsa</code> block address maps into Device Tree nodes (<code>axi_gpio</code> at <code>0x41200000</code>).</li></ol></li></ul><hr><h3 id="phase-3-yocto-system-construction-meta-xilinx" tabindex="-1">Phase 3: Yocto System Construction (<code>meta-xilinx</code>) <a class="header-anchor" href="#phase-3-yocto-system-construction-meta-xilinx" aria-label="Permalink to &quot;Phase 3: Yocto System Construction (`meta-xilinx`)&quot;">​</a></h3><ul><li><strong>Goal:</strong> Build a custom, minimal Linux distribution for ZedBoard / PYNQ using Yocto.</li><li><strong>Hands-On Tasks:</strong><ol><li>Clone Yocto Poky (<code>kirkstone</code> or <code>scarthgap</code> release):<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scarthgap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git://git.yoctoproject.org/poky</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> poky</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scarthgap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git://git.yoctoproject.org/meta-xilinx</span></span></code></pre></div></li><li>Initialize environment:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oe-init-build-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-zynq</span></span></code></pre></div></li><li>Configure <code>conf/bblayers.conf</code> to include <code>meta-xilinx-bsp</code>.</li><li>Configure <code>conf/local.conf</code>:<div class="language-bitbake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bitbake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MACHINE = &quot;zedboard-zynq7&quot; # Or &quot;pynq-z1-zynq7&quot;</span></span></code></pre></div></li><li>Build minimal image:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> core-image-minimal</span></span></code></pre></div></li><li>Flash generated <code>BOOT.BIN</code>, <code>zImage</code>, <code>system.dtb</code>, and <code>rootfs.ext4</code> to MicroSD card.</li></ol></li></ul><hr><h3 id="phase-4-device-tree-append-bbappend-uio-driver-lab" tabindex="-1">Phase 4: Device Tree Append (<code>.bbappend</code>) &amp; UIO Driver Lab <a class="header-anchor" href="#phase-4-device-tree-append-bbappend-uio-driver-lab" aria-label="Permalink to &quot;Phase 4: Device Tree Append (`.bbappend`) &amp; UIO Driver Lab&quot;">​</a></h3><ul><li><strong>Goal:</strong> Grant user-space applications direct access to FPGA registers via UIO (Userspace I/O) and Device Tree overrides.</li><li><strong>Hands-On Tasks:</strong><ol><li>Create a custom Yocto layer: <code>meta-junior-lab</code>.</li><li>Write a <code>device-tree.bbappend</code> recipe to inject custom node definitions:<div class="language-dts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&amp;axi_gpio_0 {</span></span>\n<span class="line"><span>    compatible = &quot;generic-uio&quot;;</span></span>\n<span class="line"><span>    status = &quot;okay&quot;;</span></span>\n<span class="line"><span>};</span></span></code></pre></div></li><li>Rebuild image and boot on board.</li><li>Write a C program in Linux using <code>mmap()</code> on <code>/dev/uio0</code> to toggle hardware LEDs directly from user-space!</li></ol></li></ul><hr><h2 id="📌-target-board-quick-comparison-zedboard-vs-pynq-z1-z2" tabindex="-1">📌 Target Board Quick Comparison (ZedBoard vs. PYNQ-Z1/Z2) <a class="header-anchor" href="#📌-target-board-quick-comparison-zedboard-vs-pynq-z1-z2" aria-label="Permalink to &quot;📌 Target Board Quick Comparison (ZedBoard vs. PYNQ-Z1/Z2)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature / Board</th><th style="text-align:left;">ZedBoard (Avnet)</th><th style="text-align:left;">PYNQ-Z1 / PYNQ-Z2 (TUL)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SoC Silicon</strong></td><td style="text-align:left;">Xilinx Zynq-7000 (XC7Z020-1CLG484C)</td><td style="text-align:left;">Xilinx Zynq-7000 (XC7Z020-1CLG400C)</td></tr><tr><td style="text-align:left;"><strong>CPU Cores</strong></td><td style="text-align:left;">Dual ARM Cortex-A9 @ 667 MHz</td><td style="text-align:left;">Dual ARM Cortex-A9 @ 650 MHz</td></tr><tr><td style="text-align:left;"><strong>RAM</strong></td><td style="text-align:left;">512 MB DDR3</td><td style="text-align:left;">512 MB DDR3</td></tr><tr><td style="text-align:left;"><strong>Yocto Machine Name</strong></td><td style="text-align:left;"><code>MACHINE = &quot;zedboard-zynq7&quot;</code></td><td style="text-align:left;"><code>MACHINE = &quot;pynq-z1-zynq7&quot;</code> / <code>pynq-z2-zynq7</code></td></tr><tr><td style="text-align:left;"><strong>Boot Jumpers</strong></td><td style="text-align:left;">MIO[5:3] set to <code>011</code> (SD Card)</td><td style="text-align:left;">JP5 set to <code>SD</code> position</td></tr><tr><td style="text-align:left;"><strong>Serial Console</strong></td><td style="text-align:left;">Micro-USB UART (CY7C64225 bridge)</td><td style="text-align:left;">Micro-USB FTDI UART bridge @ 115200 baud</td></tr></tbody></table><hr><div class="tip custom-block"><p class="custom-block-title">INSTRUCTOR RECOMMENDATION FOR JUNIORS</p><p>Start juniors with <strong>Phase 1 (Manual Device Tree editing with <code>dtc</code>)</strong> BEFORE introducing Yocto. If they jump straight into Yocto or PetaLinux, the automated scripts hide how U-Boot loads <code>system.dtb</code> into memory. Once they manually edit a <code>.dts</code> and compile it with <code>dtc</code>, Yocto recipes (<code>.bbappend</code>) will make complete sense!</p></div>',31)])])}const u=i(o,[["render",n]]);export{g as __pageData,u as default};
